    72	        .await
    73	        .map_err(db_error)?;
    74	    sqlx::query!("DELETE FROM exposed.funder_alias_groups")
    75	        .execute(&mut **tx)
    76	        .await
    77	        .map_err(db_error)?;
    78	    for (id, group) in &groups.memberships {
