    96	    for link in groups.family_links {
    97	        sqlx::query!("INSERT INTO exposed.funder_family_links (left_funder_id, right_funder_id, family_key, left_name, right_name) VALUES ($1, $2, $3, $4, $5)", link.left_funder_id.value(), link.right_funder_id.value(), link.family_key, link.left_name, link.right_name)
