387	    fn outcomes(
388	        &self,
389	        input: &ResolutionInput,
390	        edges: &CandidateEdges,
391	        run_key: &str,
392	    ) -> Vec<ObservationResolution> {
393	        let mut statistical = Self::new(input);
394	        let mut statistical_groups = BTreeSet::new();
395	        let mut extracted_groups = BTreeSet::new();
396	        let mut union_groups = BTreeSet::new();
397	        for candidate in edges.values() {
398	            if candidate.decision.disposition != PairDisposition::Accepted {
399	                continue;
400	            }
401	            let edge = &candidate.decision;
402	            match candidate.eligibility {
403	                EdgeEligibility::Link(LinkEvidence::Statistical) => {
404	                    statistical.join(&edge.left_funder_id, &edge.right_funder_id);
405	                    statistical_groups.insert(self.group[&edge.left_funder_id]);
406	                }
407	                EdgeEligibility::Link(LinkEvidence::ExtractedName) => {
408	                    extracted_groups.insert(self.group[&edge.left_funder_id]);
409	                }
410	                EdgeEligibility::Link(LinkEvidence::TradeUnionFamily) => {
411	                    union_groups.insert(self.group[&edge.left_funder_id]);
412	                }
413	                EdgeEligibility::Link(LinkEvidence::DonorName)
414	                | EdgeEligibility::Review
415	                | EdgeEligibility::Reject(_) => {}
416	            }
417	        }
418	        let mut observations = Vec::new();
419	        for observation in input.observations.values() {
420	            let ids = &self.members[self.group[&observation.funder_id]];
421	            let statistical_connected = ids
422	                .iter()
423	                .map(|id| statistical.group[id])
424	                .collect::<BTreeSet<_>>()
425	                .len()
426	                == 1;
427	            let component_basis = if statistical_connected {
428	                IdentityBasis::StatisticalLink
429	            } else if statistical_groups.contains(&self.group[&observation.funder_id]) {
430	                if union_groups.contains(&self.group[&observation.funder_id])
431	                    || extracted_groups.contains(&self.group[&observation.funder_id])
432	                {
433	                    IdentityBasis::StatisticalAndSupportingNameLink
434	                } else {
435	                    IdentityBasis::StatisticalAndDonorNameLink
436	                }
437	            } else if union_groups.contains(&self.group[&observation.funder_id]) {
438	                IdentityBasis::TradeUnionFamilyLink
439	            } else if extracted_groups.contains(&self.group[&observation.funder_id]) {
440	                IdentityBasis::ExtractedNameLink
441	            } else {
442	                IdentityBasis::DonorNameLink
443	            };
444	            let number = ids.iter().find_map(|id| company(&input.observations[id]));
445	            let (identity_id, identity_basis) = number.map_or_else(
446	                || {
447	                    if observation.name_normalized.is_none() {
448	                        (None, IdentityBasis::Unresolved)
449	                    } else {
450	                        let leader = ids
451	                            .first()
452	                            .expect("each observation belongs to a nonempty component")
453	                            .as_str();
454	                        (
455	                            Some(format!("run-local:{run_key}:{leader}")),
456	                            if ids.len() > 1 {
457	                                component_basis
458	                            } else {
459	                                IdentityBasis::ProvisionalSingleton
460	                            },
461	                        )
462	                    }
463	                },
464	                |number| {
465	                    (
466	                        Some(format!("source-reported:companies-house:{number}")),
467	                        if company(observation).is_some() {
468	                            IdentityBasis::SourceReportedCompany
469	                        } else {
470	                            component_basis
471	                        },
472	                    )
473	                },
474	            );
475	            observations.push(ObservationResolution {
476	                funder_id: observation.funder_id.clone(),
477	                identity_id,
478	                identity_basis,
479	            });
480	        }
481	        observations
482	    }
483	}
